head.script:
scwin.onpageload = function () {
    btn_search.hide();
    var taskData = $p.getParameter("taskData");
    console.log(taskData);
    $c.sbm.execute(sbm_designTaskTreeList);
};

scwin.sbm_designTaskTreeList_submitdone = function (e) {
    var elData = e.responseJSON.elData;
    var elHeader = e.responseJSON.elHeader;

    if (elHeader == null || elHeader == "" || elHeader == "undefined" || elHeader.resSuc == false) {
        $c.win.alert(`에러코드 : ${elHeader.resCode}\n에러메시지 : ${elHeader.resMsg}`);
        return false;
    }

    scwin.buildTreeView(elData.designVoList);
};

function getStgName(stgId) {
    var stgNames = {
        "1": "[ 1단계 ] 리서치",
        "2": "[ 2단계 ] 분석", 
        "3": "[ 3단계 ] 기획",
        "4": "[ 4단계 ] 디자인",
        "5": "[ 5단계 ] 퍼블리싱",
        "6": "[ 6단계 ] 개발"
    };
    return stgNames[stgId] || "[ " + stgId + "단계 ]";
}

scwin.buildTreeView = function (originalData) {
    var currentStgId = "";
    var stgHeaderIndex = 0;
    var taskData = $p.getParameter("taskData");
    var currentTaskId = taskData ? taskData.currentTaskId : null;
    var treeData = [];

    for (var i = 0; i < originalData.length; i++) {
        var rowData = originalData[i];

        if (currentTaskId && rowData.taskId === currentTaskId) {
            continue;
        }

        var stgId = rowData.stgId;

        if (currentStgId != stgId) {
            currentStgId = stgId;
            stgHeaderIndex++;

            treeData.push({
                taskId: "STG_" + stgId,
                taskName: getStgName(stgId),
                ptTaskId: "0",
                taskDepth: "1",
                taskSeq: stgHeaderIndex,
                stgId: stgId,
                pjtId: rowData.pjtId
            });
        }

        var taskDepth = rowData.taskDepth;
        // 단계 헤더 때문에 depth 조정: 실제 업무의 원본 depth 유지
        var adjustedDepth = parseInt(taskDepth) + 1;  // 단계 헤더로 인한 트리 구조상 +1
        var adjustedPtTaskId = taskDepth == "1" ? "STG_" + stgId : rowData.ptTaskId;

        treeData.push({
            taskId: rowData.taskId,
            taskName: rowData.taskName,
            ptTaskId: adjustedPtTaskId,
            taskDepth: adjustedDepth.toString(),
            originalDepth: taskDepth,  // 원본 depth 보존
            taskSeq: rowData.taskSeq,
            stgId: stgId,
            pjtId: rowData.pjtId
        });
    }

    dlt_taskTreeList.setJSON(treeData);
};

scwin.trv_taskTree_onlabelclick = function (value, node, index) {
    if (node && node.label) {
        if (value && value.indexOf("STG_") === 0) {
            dmp_selectedTask.set("selectedTaskId", "");
            dmp_selectedTask.set("selectedTaskName", "");
            dmp_selectedTask.set("selectedStgId", "");
            dmp_selectedTask.set("selectedTaskDepth", "");
            $c.win.alert("단계 헤더는 선택할 수 없습니다. 업무를 선택해주세요.");
        } else {
            dmp_selectedTask.set("selectedTaskId", value);
            dmp_selectedTask.set("selectedTaskName", node.label);

            var rowIndex = scwin.findRowIndexByTaskId(value);
            if (rowIndex >= 0) {
                var rowData = dlt_taskTreeList.getRowJSON(rowIndex);
                dmp_selectedTask.set("selectedStgId", rowData.stgId);
                // 원본 depth 사용 (트리 구조상 조정된 값이 아닌)
                dmp_selectedTask.set("selectedTaskDepth", rowData.originalDepth); 
            }
        }
    }
};

scwin.findRowIndexByTaskId = function (taskId) {
    for (var i = 0; i < dlt_taskTreeList.getRowCount(); i++) {
        var rowData = dlt_taskTreeList.getRowJSON(i);
        if (rowData.taskId == taskId) {
            return i;
        }
    }
    return -1;
};

scwin.btn_search_onclick = function (e) {
    $c.sbm.execute(sbm_designTaskTreeList);
};

scwin.btn_confirm_onclick = function (e) {
    var selectedTaskId = dmp_selectedTask.get("selectedTaskId");
    var selectedTaskName = dmp_selectedTask.get("selectedTaskName");
    var selectedStgId = dmp_selectedTask.get("selectedStgId");
    var selectedTaskDepth = dmp_selectedTask.get("selectedTaskDepth");

    if (selectedTaskId) {
        var taskData = $p.getParameter("taskData");

        var returnData = {
            selectedTask: {
                taskId: selectedTaskId,
                taskName: selectedTaskName,
                stgId: selectedStgId,
                taskDepth: selectedTaskDepth  
            },
            currentRowIndex: taskData ? taskData.currentRowIndex : null
        };

        $p.parent().scwin.receiveTaskData(returnData);
        $p.closePopup();
    } else {
        $c.win.alert("업무를 선택해주세요.");
    }
};

scwin.btn_cancel_onclick = function (e) {
    $p.closePopup();
};
